/*selectMasterMpSoStockApplyPopListDetail*/ SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS COM_NAME, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KR00000002') AS AGENT_NAME, A.DESCRIPTION, A.SPECIFICATION, NVL(A.ITEM_QTY,0) - (NVL(A.ITEM_QTY,0)*2) AS ITEM_QTY, NVL(A.UNIT_PRICE,0) AS UNIT_PRICE, NVL(A.AGENT_PRICE,0) AS AGENT_PRICE, (NVL(A.ITEM_QTY,0) - (NVL(A.ITEM_QTY,0)*2)) * NVL(A.UNIT_PRICE,0) AS PRICE_SUM, DECODE(#{st_stock_check_flag},'1',TO_CHAR( TO_DATE(${st_stock_date},'YYYYMMDD')+15, 'YYYYMMDD'),(SELECT TO_CHAR(LAST_DAY(TO_DATE(#{st_stock_date},'YYYYMM')),'YYYYMMDD') FROM DUAL)) AS GR_DATE, A.BUYER, A.PO_NO, A.PO_SEQ, A.GR_NO, A.GR_SEQ, A.BUYER_ITEM_NO, 'KR00000002' AS AGENT_CODE FROM ICOMGRDT A WHERE A.BUYER = #{st_buyer} AND A.PO_NO = #{st_po_no} AND A.PO_SEQ = #{st_po_seq} AND A.GR_NO = #{st_gr_no} AND A.GR_SEQ = #{st_gr_seq} AND A.STATUS <> 'D'
UNION
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS COM_NAME, DECODE(#{st_option_type},'TYPE_A',(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KR00000002')) AS AGENT_NAME, A.DESCRIPTION, A.SPECIFICATION, NVL(A.ITEM_QTY,0) AS ITEM_QTY, NVL(A.UNIT_PRICE,0) AS UNIT_PRICE, NVL(A.AGENT_PRICE,0) AS AGENT_PRICE, NVL(A.ITEM_QTY,0) * NVL(A.UNIT_PRICE,0) AS PRICE_SUM, DECODE(#{st_option_type},'TYPE_A',DECODE(#{st_stock_check_flag},'1',TO_CHAR(TO_DATE(${st_stock_date},'YYYYMMDD')+15,'YYYYMMDD'),(SELECT TO_CHAR(LAST_DAY(TO_DATE(#{st_stock_date},'YYYYMM')),'YYYYMMDD') FROM DUAL)), DECODE(#{st_stock_check_flag},'1',TO_CHAR(TO_DATE(${st_stock_date},'YYYYMMDD')+16,'YYYYMMDD'),(SELECT TO_CHAR(ADD_MONTHS(TO_DATE(#{st_stock_date},'YYYYMM'),1),'YYYYMMDD') FROM DUAL))) AS GR_DATE, A.BUYER, A.PO_NO, A.PO_SEQ, A.GR_NO, A.GR_SEQ, A.BUYER_ITEM_NO, DECODE(#{st_option_type},'TYPE_A',A.AGENT,'KR00000002') AS AGENT_CODE FROM ICOMGRDT A WHERE A.BUYER = #{st_buyer} AND A.PO_NO = #{st_po_no} AND A.PO_SEQ = #{st_po_seq} AND A.GR_NO = #{st_gr_no} AND A.GR_SEQ = #{st_gr_seq} AND A.STATUS <> 'D' ORDER BY 5

mapper.update:

UPDATE ICOMGRDT A                                                                
    SET A.STATUS           = 'R',                                                 
        A.CHANGE_DATE      = TO_CHAR(SYSDATE, 'YYYYMMDD'),                        
        A.CHANGE_TIME      = SUBSTR(TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS'),10,6),   
        A.CHANGE_USER_ID   = #{USER_ID},                 
        A.AGENT            = 'KR00000002',                                        
        A.AGENT_ITEM_AMT   = 0													 
  WHERE A.BUYER = #{BUYER}  
    AND A.PO_NO = #{PO_NO}
    AND A.PO_SEQ = #{PO_SEQ}  
    AND A.GR_NO = #{GR_NO}  
    AND A.GR_SEQ = #{GR_SEQ}  
    AND A.STATUS <> 'D'
